package br.com.sussmartcare.triage.infrastructure.messaging; import org.apache.kafka.common.TopicPartition; import org.springframework.context.annotation.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.*; import org.springframework.util.backoff.FixedBackOff; @Configuration public class TriageKafkaErrorConfig {@Bean DefaultErrorHandler errorHandler(KafkaTemplate<Object,Object> t){return new DefaultErrorHandler(new DeadLetterPublishingRecoverer(t,(r,e)->new TopicPartition(r.topic()+".DLT",r.partition())),new FixedBackOff(1000L,2L));}}
